// Adapted from organized-study-atlas-fulfillment src/server/modules/platform/auth.ts:5-45 @ d82cc29
// (Express/Prisma types removed). This is the guard in the list-membership form the
// feature doc recommends (docs/features/001-auth-rbac-shell.md:44), i.e. the state
// BEFORE the change under review.
export const knownRoles = ['viewer', 'buyer', 'warehouse_associate', 'warehouse_manager', 'admin']

export function requireRole(allowedRoles) {
  return (request, response, next) => {
    const role = request.actor?.role ?? 'viewer'

    if (!allowedRoles.includes(role)) {
      response.status(403).json({ error: 'Forbidden', requiredRoles: allowedRoles })
      return
    }

    next()
  }
}

/** test scaffolding: run a guard and report the outcome */
export function runGuard(guard, role) {
  let status = 200
  let nextCalled = false
  const response = { status(s) { status = s; return this }, json() { return this } }
  guard({ actor: role === null ? undefined : { role } }, response, () => { nextCalled = true })
  return { status, nextCalled }
}
